from google.cloud import secretmanager

class SecretManagerClient:
    def __init__(self):
        self._client = secretmanager.SecretManagerServiceClient()

    def access_secret_version(self, project_id: str, secret_id: str, version: str = "latest") -> str:
        name = f"projects/{project_id}/secrets/{secret_id}/versions/{version}"
        response = self._client.access_secret_version(request={"name": name})
        return response.payload.data.decode("utf-8")

    def add_secret_version(self, project_id: str, secret_id: str, payload_data: str) -> str:
        parent = f"projects/{project_id}/secrets/{secret_id}"
        response = self._client.add_secret_version(request={
            "parent": parent,
            "payload": {"data": payload_data.encode("utf-8")}
        })
        return response.name

    def list_secret_versions(self, project_id: str, secret_id: str):
        parent = f"projects/{project_id}/secrets/{secret_id}"
        return self._client.list_secret_versions(request={"parent": parent})

    def get_secret(self, project_id: str, secret_id: str):
        name = f"projects/{project_id}/secrets/{secret_id}"
        return self._client.get_secret(request={"name": name})

import json
from security_client import SecretManagerClient
from security_models import DbSecretPayload, SecretOutput

def fetch_db_secret(payload: DbSecretPayload) -> SecretOutput:
    client = SecretManagerClient()
    secret_value = client.access_secret_version(
        project_id=payload.project_id,
        secret_id=payload.secret_id,
        version=payload.version
    )
    if payload.key_field:
        secret_value = json.loads(secret_value)[payload.key_field]

    return SecretOutput(secret_id=payload.secret_id, value=secret_value)

from google.cloud import translate_v3 as translate
from security_models import RunbookTranslatePayload, TranslatedRunbookOutput

def runbook_translate(payload: RunbookTranslatePayload) -> TranslatedRunbookOutput:
    client = translate.TranslationServiceClient()

    parent = f"projects/{payload.project_id}/locations/global" # Global endpoint for translation

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload.text_to_translate],
            "target_language_code": payload.target_language,
            "source_language_code": payload.source_language if payload.source_language else None,
            "mime_type": "text/plain"  # Mime types: "text/plain" or "text/html"
        }
    )

    translated_text = ""
    detected_source_language = payload.source_language # Default to provided source language

    if response.translations:
        translated_text = response.translations[0].translated_text
        if not payload.source_language and response.translations[0].detected_language_code:
            detected_source_language = response.translations[0].detected_language_code

    return TranslatedRunbookOutput(
        original_text=payload.text_to_translate,
        translated_text=translated_text,
        target_language=payload.target_language,
        source_language=detected_source_language
    )
